TLM.f("Tempora/Quad1-4",{"officium":"Feria Quinta infra Hebdomadam I in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad1-0","sections":{"Introitus":[{"k":"ref","la":"Ps 95:6"},{"k":"text","la":"Conféssio et pulchritúdo in conspéctu ejus: sánctitas et magnificéntia in sanctificatióne eius."},{"k":"ref","la":"Ps 95:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: cantáte Dómino, omnis terra."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Conféssio et pulchritúdo in conspéctu ejus: sánctitas et magnificéntia in sanctificatióne eius."}],"Oratio":[{"k":"text","la":"Devotiónem pópuli tui, quǽsumus, Dómine, benígnus inténde: ut, qui per abstinéntiam macerántur in córpore, per fructum boni óperis reficiántur in mente."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Ezechiélis Prophétæ"},{"k":"ref","la":"Ezech 18:1-9"},{"k":"text","la":"In diébus illis: Factus est sermo Dómini ad me, dicens: Quid est, quod inter vos parábolam vértitis in provérbium istud in terra Israël, dicéntes: Patres comedérunt uvam acérbam, et dentes filiórum obstupéscunt? Vivo ego, dicit Dóminus Deus, si erit ultra vobis parábola hæc in provérbium in Israël. Ecce, omnes ánimæ meæ sunt: ut ánima patris, ita et ánima fílii mea est: ánima, quæ peccáverit, ipsa moriétur. Et vir si fúerit justus, et fécerit judícium et justítiam, in móntibus non coméderit, et óculos suos non leváverit ad idóla domus Israël: et uxórem próximi sui non violáverit, et ad mulíerem menstruátam non accésserit: et hóminem non contristáverit: pignus debitóri reddíderit, per vim nihil rapúerit: panem suum esuriénti déderit, et nudum operúerit vestiménto: ad usúram non commodáverit, et ámplius non accéperit: ab iniquitáte avértent manum suam, et judícium verum fécerit inter virum et virum: in præcéptis meis ambuláverit, et judícia mea custodíerit, ut fáciat veritátem: hic justus est, vita vivet, ait Dóminus omnípotens."}],"Graduale":[{"k":"ref","la":"Ps 16:8; 16:2"},{"k":"text","la":"Custódi me, Dómine, ut pupíllam óculi: sub umbra alárum tuárum prótege me."},{"k":"text","la":"De vultu tuo judícium meum pródeat: óculi tui vídeant æquitátem.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 15:21-28"},{"k":"text","la":"In illo témpore: Egréssus Jesus secéssit in partes Tyri et Sidónis. Et ecce, múlier Chananǽa a fínibus illis egréssa clamávit, dicens ei: Miserére mei, Dómine, fili David: fília mea male a dæmónio vexátur. Qui non respóndit ei verbum. Et accedéntes discípuli ejus rogábant eum, dicéntes: Dimítte eam; quia clamat post nos. Ipse autem respóndens, ait: Non sum missus nisi ad oves, quæ periérunt domus Israël. At illa venit, et adorávit eum, dicens: Dómine, ádjuva me. Qui respóndens, ait: Non est bonum súmere panem filiórum, et míttere cánibus. At illa dixit: Etiam, Dómine: nam et catélli edunt de micis, quæ cadunt de mensa dominórum suórum. Tunc respóndens Jesus, ait illi: O múlier, magna est fides tua: fiat tibi, sicut vis. Et sanáta est fília ejus ex illa hora."}],"Offertorium":[{"k":"ref","la":"Ps 33:8-9"},{"k":"text","la":"Immíttet Angelus Dómini in circúitu timéntium eum, et erípiet eos: gustáte, et vidéte, quóniam suávis est Dóminus."}],"Secreta":[{"k":"text","la":"Sacrifícia, Dómine, quǽsumus, propénsius ista nos salvent, quæ medicinálibus sunt institúta jejúniis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 6:52"},{"k":"text","la":"Panis, quem ego dédero, caro mea est pro sǽculi vita."}],"Postcommunio":[{"k":"text","la":"Tuórum nos, Dómine, largitáte donórum, et temporálibus attólle præsídiis, et rénova sempitérnis."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus.","mark":"V"},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Da, quǽsumus, Dómine, pópulis christiánis: et, quæ profiténtur, agnóscere, et cœléste munus dilígere, quod frequéntant."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7ed6e7c28135b14c":{"t":"Ps 95, 6, Ps 95, 1\n(Ps 95, 6) Slava je i krasota pred licem njegovim, svetost i veličanstvo u svetinji njegovoj. (Ps 95, 1) Pjevajte Gospodinu pjesmu novu, pjevaj Gospodinu sva zemljo!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 95, 6) Slava je i krasota pred licem njegovim, svetost i veličanstvo u svetinji njegovoj.","kn":"(Ps. 95, 6). Slava je i krasota pred licem njegovim, svetost a veličanstvo u svetinji njegovoj. (Ps. 95, 1.) Pjevajte GoiSjpcdinu pjesmu novu, pjevaj Gospodinu sva zemljo! Slava Ocu... Slava...","knRef":"Kniewald 1942, str. 674–675 (snimka 338) (OCR)"},"616bf3bd3130dcf4":{"t":"<i>Pomolimo se</i>.\nBlago pogledaj, molimo, Gospodine, na odanost svoga naroda da se oni koji se odricanjem tjelesno trape plodom dobroga djela duhovno okrijepe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"d8e5581d9aaa9110":{"t":"Ez 18, 1-9\nČitanje Ezekiela proroka. U one dane upita me Gospodin: Zašto vi u izraelskoj zemlji prepričavate kao poslovicu: Naši su oci zobali kiselo grožđe, a sinovima trnu zubi? Jamčim vam da vam to više neće biti poslovica. Evo, sve duše su moje: kao što je moja očeva duša, tako je i sinova. Umrijet će onaj koji sagriješi. Ako je tko pravedan, pa radi po pravu i pravdi, ne jede žrtvovanog, svojih očiju ne upravlja krivim bogovima, ne skvrni žene svojega bližnjega, obdržava propise zakonske čistoće, nikoga ne vrijeđa, vraća dužniku zalog, ništa silom ne otima, gladnome daje svoj zalogaj, odijeva gologa, ne daje na visoke kamate, ne čini nepravde, ljudima nepristrano sudi, živi po mojim zapovijedima, obdržava moj zakon i djeluje po istini, taj će čovjek živjeti, govori Gospodin svemogući.","kn":"Čitanje Ezekljela Proroka (18, 1-9). tJ one dane; Dođe mi riječ Gospodnja govoreći: Zašto vi među sobom obraćate priču u poslovicu ovu u zemlji Izraelskoj govoireći: Oci zobaše kiselo grožđe, a sinovima. trnu zubi? Tako ja bio živ-, govori Gospodin Bog, ne će vam više biti ova priča za poslovicu u Izraelu. Evo! sve duše moje su: kako duša očina, tako i sinovlja, moja je: duša, koja sagriješi, ona će umrijeti. A čovjek, ako je pravedain i radi po pravu i pravici, i na gorama ne jede, i očiju svojih ne podiže kumirima doma Izraelova: i ne skrvni žene iskrnjega svojega, nikoga ne vrijeđa: zalog dužniku vrača, ništa silom ne otima, kruh svoj daje gladnome i gologa odijeva; od nepravde usteže ruku svoju, i pravo sudi između jednoga čovjeka i drugoga; po zapovijedima mojim stupa 1 zakon moj opslužuje, da djeluje po istini: taj je pravedan, doista će živjeti, veli Gospodin svemogući.","knRef":"Kniewald 1942, str. 120–121 (snimka 61) (OCR)"},"2afacf948782a297":{"t":"Ps 16, 8 i 2\nČuvaj me, Gospodine, kao zjenicu oka. Sakrij me pod sjenu svojih krila. Od tvojega lica nek izađe moj sud. Tvoje oči vide što je pravo.","kn":"(Ps. 16, 2). Čuvaj me. Gospodine, kao zjenicu oka, zakloni me sjenom krila svojih. Sud moj neka iziđe od lica Tvojega; oči Tvoje neka gledaju pravdu.","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"},"22cc0620e8e8d464":{"t":"Mt 15, 21-28\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme otiđe Isus iz Galileje, i uputi se prema Tiru i Sidonu. Kananejka iz tog kraja dođe i poviče: Smiluj mi se, Gospodine, Sine Davidov! Đavao teško muči moju kćer. A on joj ne odgovori ni riječi. Približe mu se njegovi učenici i zamole ga: Daj, otpusti je, viče za nama. On odgovori: Poslan sam samo k izgubljenim ovcama doma Izraelova. Ali ona pristupi bliže, klekne preda nj i zamoli ga: Gospodine, pomozi mi! Isus joj reče: Ne valja uzeti sinovima kruh i baciti ga psićima. Ona potvrdi: Da, Gospodine, ali i psići jedu mrvice što padaju sa stola njihovih gospodara. Nato joj Isus odvrati: Ženo, velika je tvoja vjera! Neka ti bude kako želiš. I njezina kći ozdravi toga časa.","kn":"t Slijedi sv, evanđelje po Mate ju (15, 21-28). U ono vrijeme izišavši Isus odanle otiđe u krajeve Tirske i Sidonske. I gle, žena Kananejka izišavši iz onih krajeva 'POvika: Smiluj mi se, Gospodine, sine Davidov! Moju kćer vrlo muči đavao. Ali on joj ne odgovori ni riječi. Tada su pristupili njegovi učenici te su ga mcklili govoreći: Otpusti je, jer viče za nama, On odgovori; Nisam poslan nego k iz- kvatreni petak u korizmi 121 gubljenim ovcama doma Izraelova. A ona dođe i duboko mu .se klanjaše govoreći: Gospodine, ppmozi mi! Kad joj on odgovori: Nije, pravo uzeti kruh od djece i baciti (psićima; reče' pna:. Da,. Gospodine, jer i psići jedu mrvice, što padaju sa stola gospodara njihovih.. Tada joj . odgovori Isus: .Ženo! velika je vjera tvoja, '.neka se -ispuni želja tvoja! I ozdravi njezina kći od dne ure.","knRef":"Kniewald 1942, str. 120–121 (snimka 61) (OCR)"},"ecab5ba75aa2b450":{"t":"Ps 33, 8-9\nAnđeo će Gospodnji saći među one, koji ga se boje, te će ih izbaviti. Kušajte i vidite kako je dobar Gospodin.","kn":"(Ps. 33, 8, 9). Anđeo Gospodnji zaštitom svojom lebdi oko onih, koji Gospodina štuju i izbavit će ih; kušajte i vidite, kako je sladak Gospodin.","knRef":"Kniewald 1942, str. 400–401 (snimka 201) (OCR)"},"29d4a9b5c328c91a":{"t":"Ovi žrtveni prinosi, molimo, Gospodine, koji su potkrijepljeni ljekovitim postovima, neka nas to sigurnije izliječe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"e23f325e721b0af5":{"t":"Iv 6, 52\nKruh koji ću ja dati tijelo je moje za život svijeta.","kn":"(Iv. 6, 52). Kruh, koji ću ja dati, tijelo je moje za život svijeta.","knRef":"Kniewald 1942, str. 402–403 (snimka 202) (OCR)"},"3ed7ba25e5c94c3a":{"t":"<i>Pomolimo se</i>.\nObiljem nas svojih darova, Gospodine, i uzdiži vremenitom pomoću i obnovi vječnom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"109e52eff7a815fb":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nDaj, molimo, Gospodine, kršćanskom narodu da upozna istine što ih priznaje i da ljubi nebeski dar što ga prima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"nad ..pukom. Pomplirno se! Prignite ponizno . glave svoje pred Bogom! Daj, molimo. Gospodine, kršćunskiom. puku, da dobro upozna one istine, koje ispovijeda i da ljubi nebeski dar, -što ga prima, po,.G.; n. , r , .","knRef":"Kniewald 1942, str. 120–121 (snimka 61) (OCR)"}}});
